mapper.select:
select  from payment_order
where provider_version='V3' and state='CREATED' and app_id=#{appId} and mch_id=#{mchId}


        and order_id > #{afterOrderId}
        order by order_id

    order by create_time,order_id

limit #{limit}

select community_id communityId,fee_id feeId from pay_fee where 1=1
and fee_id=#{feeId}
and b_id=#{bId}
order by community_id,fee_id for update

select community_id communityId,fee_id feeId,detail_id detailId from pay_fee_detail where 1=1
and detail_id=#{detailId}
and b_id=#{bId}
order by community_id,fee_id,detail_id for update

select  
where bof.community_id=#{communityId} and b.review_state='PUBLISHED' and b.cur_bill='T'
and bof.state in ('1000','3000') and bof.bill_amount_owed > 0
and pf.end_time=bof.fee_end_time
and exists (select 1 from owner_app_user oau inner join building_owner bo
    on bo.member_id=oau.member_id and bo.community_id=oau.community_id and bo.status_cd='0'
    where oau.user_id=#{userId} and oau.community_id=bof.community_id and oau.state='12000'
    and oau.status_cd='0' and bo.owner_id=bof.owner_id)
and bof.fee_id=#{feeId}
and bof.owe_id=#{oweId}

    and bof.owe_id in #{selectedOwe}

and bof.bill_id=#{billId}
and pf.payer_obj_id=#{roomId} and bof.payer_obj_type=#{payObjType}
order by bof.owe_id
for update

mapper.update:
update pay_fee pf inner join pay_fee_config pfc on pf.config_id=pfc.config_id and pf.community_id=pfc.community_id
set pf.end_time=#{deadlineTime},pf.state=case when pf.fee_flag='2006012' or #{deadlineTime}>pfc.end_time then '2009001' else '2008001' end
where pf.fee_id=#{feeId} and pf.community_id=#{communityId} and pf.status_cd='0' and pf.end_time=#{feeEndTime}
